$c0 = $p;
$c1 = $p - 1;

$N1 = (int)(($M - 1) / 3) + 1;
$sum_d1 = $M * $N1 - 3 * (($N1 - 1) * $N1) / 2 - $N1;
$c2 = $sum_d1 % MOD;

$N2 = (int)($M / 3);
$sum_d2 = $M * $N2 - 3 * ($N2 * ($N2 + 1) / 2);
$c3 = $sum_d2 % MOD;

$c0_mod = $c0 % MOD;
